# -*- coding: utf-8 -*-
"""
HOÀN THIỆN SÁP NHẬP TOÀN CẤP - BƯỚC 2: TÁCH LIÊN CẤP/ĐẶC THÙ
Không thực hiện sáp nhập; không chủ động ghi phocap.db.
"""
from __future__ import annotations
import base64, datetime as dt, hashlib, json, os, py_compile, shutil, subprocess, sys, tempfile
from pathlib import Path

TITLE = 'HOÀN THIỆN SÁP NHẬP TOÀN CẤP - BƯỚC 2: TÁCH LIÊN CẤP/ĐẶC THÙ'
EMBEDDED_FILES = {'app/services/school_merger_level_batch_service.py': '', 'app/templates/data_tools/school_merger_level_batch.html': ''}
DASHBOARD_REL = 'app/templates/data_tools/school_merger_dashboard_v45.html'
SMOKE_CODE = 'import json\nfrom app.services.school_merger_level_batch_service import build_level_batch_preview\np=build_level_batch_preview(school_year_id=2, level_code="TH")\nfor row in p.get("rows") or []:\n    levels={str(x or "").strip().upper() for x in (row.get("level_codes") or []) if str(x or "").strip()}\n    assert levels=={"TH"}, (row.get("id"), levels)\nassert int(p.get("excluded_cross_level_count") or 0) >= 1\nout={\n "pure_total":p.get("total"),\n "keep":(p.get("counts") or {}).get("KEEP"),\n "done":(p.get("counts") or {}).get("DONE"),\n "ready":p.get("candidate_count"),\n "block":p.get("effective_block_count"),\n "cross_level_excluded":p.get("excluded_cross_level_count"),\n "ready_for_execution":p.get("ready_for_execution"),\n}\nprint(json.dumps(out,ensure_ascii=True,default=str))'


def db_fingerprint(db: Path) -> str:
    h=hashlib.sha256(); found=False
    for p in (db, Path(str(db)+'-wal')):
        if p.exists():
            found=True; h.update(p.name.encode('utf-8'))
            with p.open('rb') as f:
                for c in iter(lambda:f.read(1024*1024), b''):
                    h.update(c)
    return h.hexdigest() if found else 'MISSING'


def locate_root() -> Path:
    for c in (Path.cwd(), Path(r"C:\PhoCap"), Path(__file__).resolve().parent):
        if (c/'app'/'main.py').exists() and (c/'data'/'phocap.db').exists():
            return c.resolve()
    raise RuntimeError(r"Không tìm thấy dự án. Hãy chép bộ cài vào C:\PhoCap rồi chạy lại.")


def atomic_write(path: Path, data: bytes) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    fd,tmp=tempfile.mkstemp(prefix=path.name+'.',suffix='.tmp',dir=str(path.parent))
    try:
        with os.fdopen(fd,'wb') as f:
            f.write(data); f.flush(); os.fsync(f.fileno())
        os.replace(tmp,path)
    finally:
        if os.path.exists(tmp):
            try: os.unlink(tmp)
            except Exception: pass


def patch_dashboard(text: str) -> str:
    replacements = [
        ('PASS – CÓ THỂ XEM TRƯỚC','ĐẠT NGUỒN – CÓ THỂ XEM TRƯỚC'),
        ('PASS CÓ THỂ XEM TRƯỚC','ĐẠT NGUỒN CÓ THỂ XEM TRƯỚC'),
        ('BLOCK – CẦN XỬ LÝ','CHẶN – CẦN XỬ LÝ'),
        ('BLOCK CẦN XỬ LÝ','CHẶN CẦN XỬ LÝ'),
        ('Xuất Excel BLOCK','Xuất Excel cần xử lý'),
        ('Không có chức năng sáp nhập hàng loạt; mỗi phương án vẫn phải qua kiểm tra dữ liệu nguồn + khóa trạng thái bản xem trước + mô phỏng + xác nhận.',
         'Sáp nhập toàn cấp chỉ mở khi không còn phương án CHẶN; các phương án vẫn được kiểm tra dữ liệu nguồn, bản xem trước và mô phỏng trước khi thực hiện.'),
        ('Không có chức năng sáp nhập hàng loạt; mỗi phương án vẫn qua V4.3 + V4.1 + mô phỏng + xác nhận.',
         'Sáp nhập toàn cấp chỉ mở khi không còn phương án CHẶN; các phương án vẫn được kiểm tra dữ liệu nguồn, bản xem trước và mô phỏng trước khi thực hiện.'),
    ]
    for a,b in replacements:
        text=text.replace(a,b)
    old='<span class="badge {{ p.dashboard_state|lower }}">{{ p.dashboard_label }}</span>'
    new='<span class="badge {{ p.dashboard_state|lower }}">{% if p.dashboard_state==\'READY\' %}ĐẠT NGUỒN – CÓ THỂ XEM TRƯỚC{% elif p.dashboard_state==\'BLOCK\' %}CHẶN – CẦN XỬ LÝ{% else %}{{ p.dashboard_label }}{% endif %}</span>'
    text=text.replace(old,new)
    text=text.replace('<li>{{ r }}</li>', '<li>{{ r|replace(\'V4.3\',\'kiểm tra dữ liệu nguồn\')|replace(\'V4.1\',\'bản xem trước\')|replace(\'MAPPED\',\'đã xác định nguồn → đích\') }}</li>')
    return text


def main():
    root=locate_root(); db=root/'data'/'phocap.db'
    stamp=dt.datetime.now().strftime('%Y%m%d_%H%M%S')
    backup=root/'backups'/f'backup_truoc_tach_lien_cap_sap_nhap_toan_cap_{stamp}'
    touched=list(EMBEDDED_FILES)+[DASHBOARD_REL]
    db_before=db_fingerprint(db)
    print('='*112); print(TITLE); print(f'Dự án: {root}'); print(f'Database: {db}')
    print('Nguyên tắc: KHÔNG thực hiện sáp nhập; KHÔNG chủ động ghi phocap.db.'); print('='*112)
    try:
        service_path=root/'app/services/school_merger_level_batch_service.py'
        template_path=root/'app/templates/data_tools/school_merger_level_batch.html'
        dash_path=root/DASHBOARD_REL
        if not service_path.exists() or not template_path.exists() or not dash_path.exists():
            raise RuntimeError('Thiếu chức năng Sáp nhập toàn cấp hiện tại. Hãy cài bộ Sáp nhập toàn cấp trước.')
        src=service_path.read_text(encoding='utf-8')
        for marker in ('def build_level_batch_preview','def execute_level_batch','LEVEL_BATCH_CONFIRM_PHRASE'):
            if marker not in src:
                raise RuntimeError(f'Tệp dịch vụ toàn cấp không đúng nền chức năng: thiếu {marker}')
        if 'Sáp nhập toàn cấp' not in template_path.read_text(encoding='utf-8'):
            raise RuntimeError('Template Sáp nhập toàn cấp không đúng nền chức năng.')

        backup.mkdir(parents=True,exist_ok=True)
        for rel in touched:
            p=root/rel
            if p.exists():
                bp=backup/rel; bp.parent.mkdir(parents=True,exist_ok=True); shutil.copy2(p,bp)

        for rel,b64 in EMBEDDED_FILES.items():
            atomic_write(root/rel, base64.b64decode(b64))
        atomic_write(dash_path, patch_dashboard(dash_path.read_text(encoding='utf-8')).encode('utf-8'))

        py_compile.compile(str(service_path),doraise=True)
        from jinja2 import Environment
        env=Environment(); env.parse(template_path.read_text(encoding='utf-8')); env.parse(dash_path.read_text(encoding='utf-8'))

        envp=os.environ.copy(); envp['PYTHONPATH']=str(root); envp['PYTHONIOENCODING']='utf-8'
        cp=subprocess.run([sys.executable,'-c',SMOKE_CODE],cwd=str(root),env=envp,capture_output=True,text=True,timeout=180)
        if cp.returncode!=0:
            raise RuntimeError('Smoke audit sau cài lỗi:\n'+(cp.stdout or '')+'\n'+(cp.stderr or ''))
        smoke_data=json.loads((cp.stdout or '').strip().splitlines()[-1])
        if db_fingerprint(db)!=db_before:
            raise RuntimeError('Database thay đổi trong lúc cài/smoke audit. Dừng và khôi phục mã nguồn.')

        print('CÀI ĐẶT THÀNH CÔNG')
        print('Database: KHÔNG THAY ĐỔI')
        print(f"Tiểu học thuần: tổng {smoke_data['pure_total']} | GIỮ NGUYÊN {smoke_data['keep']} | ĐÃ THỰC HIỆN {smoke_data['done']} | ĐẠT {smoke_data['ready']} | CHẶN {smoke_data['block']}")
        print(f"Liên cấp/đặc thù có Tiểu học đã tách riêng: {smoke_data['cross_level_excluded']} phương án")
        print('Nguyên tắc mới: batch MN/TH/THCS chỉ chạy phương án thuộc DUY NHẤT cấp đó; liên cấp xử lý bằng đợt riêng.')
        print(f'Backup mã nguồn trước cài: {backup}')
        print('='*112)
    except Exception as exc:
        try:
            for rel in touched:
                bp=backup/rel; p=root/rel
                if bp.exists():
                    p.parent.mkdir(parents=True,exist_ok=True); shutil.copy2(bp,p)
        except Exception:
            pass
        print('\n'+'='*112)
        print('DỪNG AN TOÀN - '+TITLE)
        print('Mã nguồn đã được khôi phục nếu đã chạm file.')
        print('Lỗi:',exc)
        print('Bộ cài KHÔNG thực hiện sáp nhập và KHÔNG chủ động ghi phocap.db.')
        print('='*112)
        raise SystemExit(1)

if __name__=='__main__':
    main()
